package com.twinlore.app.data.vgmaps

import android.content.Context
import com.twinlore.app.data.canonicalMatchTokens
import com.twinlore.app.data.numberSignature
import dagger.hilt.android.qualifiers.ApplicationContext
import org.json.JSONArray
import javax.inject.Inject
import javax.inject.Singleton

/**
 * In-memory directory of vgmaps.com entries loaded once from a bundled JSON
 * asset. Provides fuzzy lookup of a vault game name to a list of candidate
 * [VgmapsEntry] rows (often one, sometimes one per system).
 *
 * The JSON is generated by `VgmapsCatalogRegeneratorTest` from a saved copy
 * of the vgmaps directory MHT.
 */
@Singleton
class VgmapsCatalog @Inject constructor(
    @ApplicationContext private val appContext: Context,
) {
    private val entries: List<VgmapsEntry> by lazy {
        val json = appContext.assets.open(ASSET_PATH).bufferedReader().use { it.readText() }
        parse(json)
    }

    fun match(gameName: String): List<VgmapsEntry> = scoreAndRank(entries, gameName)

    companion object {
        const val ASSET_PATH = "vgmaps_catalog.json"
        const val MATCH_THRESHOLD = 0.6
        const val MAX_RESULTS = 4

        /** Test-only factory that bypasses the assets pipeline. */
        fun fromJson(json: String): VgmapsCatalogTesting = VgmapsCatalogTesting(parse(json))

        internal fun parse(json: String): List<VgmapsEntry> {
            val arr = JSONArray(json)
            val out = ArrayList<VgmapsEntry>(arr.length())
            for (i in 0 until arr.length()) {
                val o = arr.getJSONObject(i)
                out += VgmapsEntry(
                    title = o.getString("t"),
                    system = o.getString("s"),
                    anchor = o.getString("a"),
                )
            }
            return cleanAndDedupe(out)
        }

        /**
         * Defends against scraping artifacts in the catalog: drops entries whose title
         * is just a parenthesized system tag (e.g. `(Amiga)`, `(GBA)` — leftovers from
         * `<a>` tags that wrap only the suffix text on the source page), then collapses
         * entries that share a `(system, anchor)` pair to a single row by keeping the
         * shortest non-orphan title. Resolves the "I see two GBA tabs for the same
         * game" symptom and shrinks the loaded set by ~30%.
         */
        internal fun cleanAndDedupe(entries: List<VgmapsEntry>): List<VgmapsEntry> {
            val orphanTitle = Regex("""^\s*\(.+\)\s*$""")
            return entries
                .asSequence()
                .filterNot { orphanTitle.matches(it.title) }
                .groupBy { it.system to it.anchor }
                .values
                .mapNotNull { group ->
                    group.minWithOrNull(compareBy({ it.title.length }, { it.title }))
                }
        }

        internal fun scoreAndRank(entries: List<VgmapsEntry>, gameName: String): List<VgmapsEntry> {
            if (gameName.isBlank()) return emptyList()
            // Canonical tokens (region tags stripped, Roman→Arabic) shared with
            // StrategyWikiCatalog — see com.twinlore.app.data.NameNumerals.
            val inputTokenList = canonicalMatchTokens(gameName)
            if (inputTokenList.isEmpty()) return emptyList()
            val inputTokens = inputTokenList.toSet()
            val inputNumbers = numberSignature(inputTokenList)
            val normInput = inputTokenList.joinToString(" ")

            data class Scored(val entry: VgmapsEntry, val score: Double, val isPrefix: Boolean, val titleLen: Int)

            val scored = entries.mapNotNull { e ->
                val titleTokenList = canonicalMatchTokens(e.title)
                // Sequel guard: a base game never matches a numbered sequel and
                // "2" never matches "3" (Roman/Arabic already unified above).
                if (numberSignature(titleTokenList) != inputNumbers) return@mapNotNull null
                val titleTokens = titleTokenList.toSet()
                val intersect = inputTokens.intersect(titleTokens).size
                val union = inputTokens.union(titleTokens).size
                if (union == 0) return@mapNotNull null
                val score = intersect.toDouble() / union.toDouble()
                if (score < MATCH_THRESHOLD) return@mapNotNull null
                val normTitle = titleTokenList.joinToString(" ")
                Scored(e, score, normTitle.startsWith(normInput), normTitle.length)
            }

            return scored
                .sortedWith(
                    compareByDescending<Scored> { it.score }
                        .thenByDescending { it.isPrefix }
                        .thenBy { it.titleLen }
                        .thenBy { it.entry.title }
                        .thenBy { it.entry.system }
                )
                .take(MAX_RESULTS)
                .map { it.entry }
        }
    }
}

/**
 * Test-only wrapper that exposes the matcher without needing an Android Context.
 * Kept in this file so it can call the internal scoreAndRank helper.
 */
class VgmapsCatalogTesting internal constructor(private val entries: List<VgmapsEntry>) {
    fun match(gameName: String): List<VgmapsEntry> = VgmapsCatalog.scoreAndRank(entries, gameName)
}
